const body = {
  messages: [
    { role: 'assistant', content: "Hello, I'm your Hologram Guide." },
    { role: 'user', content: 'Give me a quick overview of Agentic RAG.' }
  ],
  mode: 'fast' // or 'accurate'
};

const res = await fetch('/api/hologram-agent/chat', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(body)
});
const data = await res.json();
